// All Star page, redesign: the store's reward on top with its breakdown (month by month, by range, by part) and an Excel
// download; then a card per All Stars Hero with photo, reward and how it adds up (quarter or latest month). Heroes can add
// their own photo; Heroes see parts, units and their reward, never the store's buy prices or product values.
// Database: stravik_as_owner_breakdown(), stravik_as_counter(), stravik_hero_photo_set(), bucket stravik-hero-photos.
const fs = require("fs");
function edit(file, pairs) {
  let s = fs.readFileSync(file, "utf8");
  for (const [from, to] of pairs) {
    const n = s.split(from).length - 1;
    if (n !== 1) { console.error(`${file}: expected the text once, found it ${n} times: ${from.slice(0, 70)}`); process.exit(1); }
    s = s.replace(from, () => to);
  }
  fs.writeFileSync(file, s);
  console.log(file + ": updated");
}
