{ const f = "assets/allstar.css", s = fs.readFileSync(f, "utf8"); if (s.includes(".hz-top{")) { console.error(f + ": already there"); process.exit(1); } fs.writeFileSync(f, s + "\n/* ---- redesign: the store's reward on top (with its breakdown), the Heroes' cards below */\n.hz-top{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.15fr);gap:10px 36px;align-items:start}\n.hz-top .as-track{margin-top:6px}\n.hz-acts{display:flex;flex-wrap:wrap;gap:10px;margin-top:16px}\n.hz-break{margin-top:8px;border-top:1px solid var(--line);padding-top:6px}\n.hz-tier{display:inline-block;padding:2px 10px;border-radius:999px;font-weight:700;font-size:13px}\n.hz-tier.bronze{background:rgba(184,115,58,.16);color:#7a4417}\n.hz-tier.silver{background:rgba(142,154,166,.22);color:#3d4852}\n.hz-tier.gold{background:rgba(201,154,28,.2);color:#6b5000}\n.hz-ranges{display:grid;gap:8px}\n.hz-ranges div{display:grid;grid-template-columns:170px minmax(0,1fr) auto;gap:12px;align-items:center;font-size:14.5px}\n.hz-ranges span:last-child{color:var(--muted);white-space:nowrap}\n.hz-rbar{height:10px;border-radius:999px;background:var(--paper);overflow:hidden}\n.hz-rbar i{display:block;height:100%;width:0;background:linear-gradient(90deg,var(--as-bronze),var(--as-gold));transition:width 1s cubic-bezier(.2,.8,.2,1)}\n.as-dash>.as-store{margin-bottom:0}\n.hz-heroes{margin-top:22px;border-top:6px solid var(--as-ink)}\n.hz-switch{display:inline-flex;border:1px solid var(--line);border-radius:999px;overflow:hidden}\n.hz-switch button{font:inherit;font-size:13.5px;font-weight:600;padding:6px 14px;border:0;background:var(--card);color:var(--muted);cursor:pointer}\n.hz-switch button[aria-pressed=\"true\"]{background:var(--as-ink);color:#fff}\n.hz-sum{display:grid;grid-template-columns:auto minmax(0,1fr);gap:4px 28px;align-items:end;margin-bottom:14px}\n.hz-sum .as-sub{margin:0 0 8px}\n.hz-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:14px}\n.hz-card{position:relative;display:flex;flex-direction:column;gap:8px;padding:16px;border:1px solid var(--line);border-radius:14px;background:var(--card);transition:transform .15s,box-shadow .15s}\n.hz-card:hover{transform:translateY(-2px);box-shadow:0 10px 24px rgba(11,32,61,.08)}\n.hz-card.r1{border-color:var(--as-gold);background:linear-gradient(180deg,rgba(201,154,28,.12),transparent 60%),var(--card)}\n.hz-card.r2{border-color:var(--as-silver);background:linear-gradient(180deg,rgba(142,154,166,.14),transparent 60%),var(--card)}\n.hz-card.r3{border-color:var(--as-bronze);background:linear-gradient(180deg,rgba(184,115,58,.12),transparent 60%),var(--card)}\n.hz-card.quiet,.hz-card.un{opacity:.78}\n.hz-head{position:relative;display:flex;align-items:center;gap:12px}\n.hz-av{position:relative;flex:none;display:grid;place-items:center;width:64px;height:64px;border-radius:50%;overflow:hidden;background:var(--paper);border:3px solid var(--line);font-weight:800;font-size:20px;color:var(--ink)}\n.hz-av img{width:100%;height:100%;object-fit:cover}\n.hz-av.r1{border-color:var(--as-gold)} .hz-av.r2{border-color:var(--as-silver)} .hz-av.r3{border-color:var(--as-bronze)}\n.hz-av.big{width:108px;height:108px;font-size:32px;border-width:4px}\n.hz-rank{position:absolute;left:44px;top:42px;display:grid;place-items:center;width:26px;height:26px;border-radius:50%;font-weight:800;font-size:13px;box-shadow:0 0 0 2px var(--card)}\n.hz-card.r1 .hz-rank{background:radial-gradient(circle at 35% 30%,var(--as-gold2),var(--as-gold));color:#3b2a00}\n.hz-card.r2 .hz-rank{background:radial-gradient(circle at 35% 30%,#fff,var(--as-silver));color:#1f2a33}\n.hz-card.r3 .hz-rank{background:radial-gradient(circle at 35% 30%,var(--as-bronze2),var(--as-bronze));color:#2e1500}\n.hz-name{display:grid;min-width:0}\n.hz-name b{font-size:16.5px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.hz-name span{color:var(--muted);font-size:13.5px}\n.hz-amt{font-family:var(--display);font-weight:700;font-size:30px;font-variant-numeric:tabular-nums;color:var(--ink)}\n.hz-card.r1 .hz-amt{color:var(--as-gold)}\n.hz-bar{height:8px;border-radius:999px;background:var(--paper);overflow:hidden}\n.hz-bar i{display:block;height:100%;width:0;border-radius:999px;background:linear-gradient(90deg,var(--as-gold2),var(--as-gold));transition:width 1s cubic-bezier(.2,.8,.2,1)}\n.hz-cacts{display:flex;flex-wrap:wrap;gap:6px 16px;font-size:14px}\n.hz-detail{border-top:1px solid var(--line);padding-top:8px;font-size:13.5px}\n.hz-detail table{width:100%;border-collapse:collapse;margin-bottom:8px}\n.hz-detail th,.hz-detail td{padding:4px 0;text-align:left;border-bottom:1px solid var(--line)}\n.hz-detail .n{text-align:right}\n.hz-parts{list-style:none;margin:6px 0;padding:0;display:grid;gap:4px}\n.hz-parts li{display:grid;grid-template-columns:auto minmax(0,1fr) auto;gap:8px;align-items:baseline;font-size:13.5px}\n.hz-parts li span{color:var(--muted);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.hz-parts li em{font-style:normal;font-weight:700}\n.hz-add{align-items:center;justify-content:center;text-align:center;font:inherit;border-style:dashed;cursor:pointer;color:var(--ink)}\n.hz-add .hz-av{font-size:28px;color:var(--muted)}\n.hz-me{display:flex;flex-direction:column;align-items:center;gap:6px;margin-bottom:8px}\n.hz-how{text-align:left;margin-top:12px;border-top:1px solid var(--line);padding-top:8px}\n.hz-how summary{cursor:pointer;font-weight:700}\n@media (max-width:900px){.hz-top,.hz-sum{grid-template-columns:1fr}.hz-ranges div{grid-template-columns:120px minmax(0,1fr)}.hz-ranges span:last-child{grid-column:1/-1}}\n@media (prefers-reduced-motion:reduce){.hz-bar i,.hz-rbar i{transition:none}.hz-card:hover{transform:none}}\n"); console.log(f + ": updated"); }
